import {TASKS,SECTIONS,RHYTHM,WEEKS,MILESTONES,PROJECT_ID} from './data.js';
import {renderRoadmap} from './roadmap.js';
import {MEMBER_IDS,allSeeds,baseId,uid,newEvent,entities,entityHeads,sortEvents,votesFor,memberNames,stepState,taskStats,recentStatus,materialStatus,logsFor,hoursFor,costsFor,validateEvent,parseTransfer,transfer,reconcile,conflictingEntities,latestPerMember,isKleinanzeigenUrl,offerTotal,sortedOffers,approvalRequest,checkApprovalRequest} from './core.js';

const dbName='werkstatt-gemeinschaft-v1';
let db,events=[],deviceId='',actor='a',page='dashboard',selectedTask=null,filterSection='alle',filterSearch='',filterApproval='alle',modalType='',renderPending=false;
const nav=[['dashboard','Roadmap','◇'],['tasks','Aufgaben','☑'],['calendar','Termine','▣'],['votes','Abstimmung','◉'],['materials','Material','▤'],['offers','Kleinanzeigen','⌕'],['logs','Protokolle','≡'],['sync','Synchronisieren','⇄']];
const $=s=>document.querySelector(s);
const esc=(s='')=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(Number(x||0));
const num=x=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:1}).format(Number(x||0));
const niceDate=x=>x?new Date(x+'T12:00:00').toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric'}):'–';
const names=()=>memberNames(events);
const who=id=>names()[id]||id;
const E=type=>entities(events,type);
const findE=(type,id)=>E(type).find(x=>x.id===id);
const vote=(type,x)=>votesFor(events,type,x);
const statusPill=(v)=>`<span class="pill ${v==='approved'?'approved':v==='rueckfrage'?'rueckfrage':v==='konflikt'?'konflikt':'pending'}">${v==='approved'?'3/3 FREIGEGEBEN':v==='rueckfrage'?'ÄNDERUNG / ABGELEHNT':v==='konflikt'?'KONFLIKT':'FREIGABE OFFEN'}</span>`;
const tstatus=e=>{if(e.conflict)return 'Konflikt';const v=vote('task',e);if(v.state!=='approved')return 'Gesperrt';const s=taskStats(events,e);if(s.total>0&&s.done===s.total)return 'Erledigt';return recentStatus(events,e.id)};
function toast(s,bad=false){const el=$('#toast');el.textContent=s;el.classList.toggle('bad',bad);el.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.remove('show'),4500)}
function opendb(){return new Promise((resolve,reject)=>{const r=indexedDB.open(dbName,1);r.onupgradeneeded=()=>{const d=r.result;d.createObjectStore('events',{keyPath:'id'});d.createObjectStore('meta',{keyPath:'key'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function txPut(store,items,clear=false){return new Promise((resolve,reject)=>{const t=db.transaction(store,'readwrite'),s=t.objectStore(store);if(clear)s.clear();for(const e of items)s.put(e);t.oncomplete=resolve;t.onerror=()=>reject(t.error)})}
function txAll(store){return new Promise((resolve,reject)=>{const t=db.transaction(store,'readonly');const r=t.objectStore(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function meta(key,value){if(arguments.length===1)return (await txAll('meta')).find(x=>x.key===key)?.value;await txPut('meta',[{key,value}]);return value}
async function reload(){events=sortEvents(await txAll('events'));render()}
async function append(e){if(!validateEvent(e))throw new Error('Ungültige Änderung.');await txPut('events',[e]);events.push(e);events=sortEvents(events);try{new BroadcastChannel('werkstatt-sync').postMessage('changed')}catch{}render();return e}
function headParent(type,id){const e=findE(type,id);if(!e||e.conflict)throw new Error('Bitte zuerst den Änderungskonflikt lösen.');return e.revision?[e.revision.id]:[]}
const rawNotes=s=>esc(s).replaceAll('\n','<br>');
function formVal(f,n){return f.elements.namedItem(n)?.value??''}
function formNum(f,n){return Math.max(0,Number(formVal(f,n))||0)}
function currentActor(){return actor}
function eventOf(kind,id,data,parents=[]){return newEvent(kind,id,currentActor(),data,parents,deviceId)}
function pageHeading(eyebrow,title,sub,button=''){return `<div class="pageheader"><div><div class="eyebrow accent">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${button}</div>`}
function groupFor(e){return SECTIONS.find(s=>s.id===e.data?.section)?.title||'Sonstiges'}
function stats(){const tasks=E('task'),mats=E('material'),valid=tasks.filter(t=>!t.conflict);const finished=valid.filter(t=>tstatus(t)==='Erledigt').length;const totalSteps=valid.reduce((s,t)=>s+taskStats(events,t).total,0);const doneSteps=valid.filter(t=>vote('task',t).state==='approved').reduce((s,t)=>s+taskStats(events,t).done,0);const pending=tasks.filter(t=>vote('task',t).state!=='approved').length+mats.filter(t=>vote('material',t).state!=='approved').length+E('offer').filter(t=>vote('offer',t).state!=='approved').length;const hours=hoursFor(events),cost=costsFor(events);const planHours=valid.reduce((s,t)=>s+Number(t.data?.personHours||0),0);const planCost=valid.reduce((s,t)=>s+Number(t.data?.budget||0),0)+mats.filter(m=>m.data&&!m.data.taskId).reduce((s,t)=>s+Number(t.data?.estimate||0),0);return {tasks,finished,totalSteps,doneSteps,pending,hours,planHours,cost,planCost};}
function sectionProgress(section){const xs=E('task').filter(t=>t.data?.section===section);return {all:xs.length,done:xs.filter(t=>tstatus(t)==='Erledigt').length}}
function topnav(){const a=names(),s=stats();const html=nav.map(([id,title,icon])=>`<button class="navitem ${page===id?'active':''}" data-page="${id}"><span class="navicon">${icon}</span><span>${title}</span>${id==='votes'&&s.pending?`<span class="counter">${s.pending}</span>`:''}</button>`).join('');$('#sidenav').innerHTML=html;$('#mobileNav').innerHTML=html;$('#actorSelect').innerHTML=MEMBER_IDS.map(id=>`<option value="${id}" ${actor===id?'selected':''}>${esc(a[id])}</option>`).join('');$('#crumb').textContent=nav.find(x=>x[0]===page)?.[1];}
function render(){if(!db)return;topnav();const pages={dashboard:renderDashboard,tasks:renderTasks,calendar:renderCalendar,votes:renderVotes,materials:renderMaterials,logs:renderLogs,offers:renderOffers,sync:renderSync};$('#content').innerHTML=pages[page]();}
function go(p){page=p;location.hash=p;render();window.scrollTo({top:0,behavior:'instant'})}
function renderDashboard(){return renderRoadmap({tasks:E('task'),materials:E('material'),offers:E('offer'),sessions:E('session'),events,vote,taskStats,tstatus,hoursFor,costsFor,actor,who,lastImport:localStorage.getItem('werkstatt-last-import')});}
function taskCard(t){const d=t.data||t.heads[0]?.data||{};const v=vote('task',t),p=taskStats(events,t),st=tstatus(t);return `<article class="taskCard"><div class="taskTop"><div class="taskbody"><div class="taskmeta"><span class="tasknum">${esc(t.id)}</span><span>Woche ${esc(d.week||'–')}</span><span>${esc(d.room||'Alle Räume')}</span></div><h3>${esc(d.title||'Konflikt – Aufgabe')}</h3><div class="taskmeta"><span>${esc(groupFor(t))}</span>${d.expert?'<span class="pill info">FACHPERSON</span>':''}<span>Koordination: ${esc((d.assignees||[]).map(who).join(', ')||'offen')}</span></div></div>${statusPill(t.conflict?'konflikt':v.state)}</div><div class="taskBottom"><div style="display:flex;align-items:center;gap:8px;min-width:0"><span class="pill ${st==='Erledigt'?'done':st==='Gesperrt'?'blocked':'soft'}">${esc(st)}</span><span class="muted smalltxt">${p.done}/${p.total} Schritte · ${money(d.budget||0)}</span></div><button class="btn small" data-task="${esc(t.id)}">Details →</button></div><div class="progress" style="margin-top:11px"><b style="width:${p.total?Math.round(p.done/p.total*100):0}%"></b></div></article>`}
function renderTasks(){let tasks=E('task').filter(x=>filterSection==='alle'||x.data?.section===filterSection).filter(x=>(x.data?.title||'').toLowerCase().includes(filterSearch.toLowerCase())||x.id.toLowerCase().includes(filterSearch.toLowerCase()));return `${pageHeading('01 / GEMEINSAME ARBEIT','Aufgaben & Arbeitspakete','20 übergeordnete Gemeinschaftsaufgaben mit 49 dokumentierbaren Einzelschritten. Zuweisungen regeln die Koordination – keine festen Gewerke.','<button class="btn primary" data-add-task="1">＋ Neues Vorhaben</button>')}<div class="filterbar"><input id="searchTasks" placeholder="Aufgabe suchen …" value="${esc(filterSearch)}" aria-label="Aufgaben suchen"><select id="sectionFilter" aria-label="Priorität filtern"><option value="alle">Alle Prioritäten</option>${SECTIONS.map(s=>`<option value="${s.id}" ${s.id===filterSection?'selected':''}>${esc(s.id+' – '+s.title)}</option>`).join('')}</select><span class="pill soft">${tasks.length} Einträge</span></div><div class="sectionlist">${tasks.length?tasks.map(taskCard).join(''):'<div class="empty">Keine Aufgaben gefunden.</div>'}</div>`}
function renderVotes(){const targets=[...E('task').map(x=>({...x,type:'task'})),...E('material').map(x=>({...x,type:'material'})),...E('offer').map(x=>({...x,type:'offer'}))].filter(x=>filterApproval==='alle'||vote(x.type,x).state===filterApproval);const pending=targets.filter(x=>vote(x.type,x).state!=='approved');return `${pageHeading('02 / EINSTIMMIGKEIT','Abstimmung & Freigabe','Jede Aufgabenfassung und jede Beschaffung benötigt drei Zustimmungen. Ablehnung oder Änderungsvorschlag sperrt die Freigabe.')}<div class="notice warn"><strong>Vertrauensbasis:</strong> Die Auswahl des aktiven Mitglieds ist keine Identitätsprüfung. Stimmen gelten nur für die unveränderte Version; nach Änderungen muss erneut abgestimmt werden. Datenaustausch erfolgt per JSON.</div><div class="filterbar spacing"><select id="approvalFilter"><option value="alle">Alle Anträge</option><option value="pending" ${filterApproval==='pending'?'selected':''}>Offen</option><option value="rueckfrage" ${filterApproval==='rueckfrage'?'selected':''}>Änderungen / Ablehnungen</option><option value="approved" ${filterApproval==='approved'?'selected':''}>Freigegeben</option><option value="konflikt" ${filterApproval==='konflikt'?'selected':''}>Konflikte</option></select><span class="pill soft">${pending.length} nicht freigegeben</span></div><div class="sectionlist">${targets.map(t=>{const d=t.data||t.heads[0]?.data||{},v=vote(t.type,t);return `<div class="taskCard"><div class="taskTop"><div class="taskbody"><div class="tasknum">${t.type==='task'?'ARBEITSPAKET':t.type==='material'?'BESCHAFFUNG':'KLEINANZEIGE'} · ${esc(t.id)}</div><h3>${esc(d.title)}</h3><div class="taskmeta">${t.type==='task'?`Zeit: ${num(d.calendarHours||0)} h · ${num(d.personHours||0)} Personen-h · `:''}Budget: ${money(t.type==='task'?d.budget:t.type==='material'?d.estimate:offerTotal(d))}</div></div>${statusPill(t.conflict?'konflikt':v.state)}</div><div class="spacing voters">${MEMBER_IDS.map(m=>{const choice=v.votes[m]?.data.choice;return `<div class="voter"><span class="who">${esc(who(m))}</span><span class="pill ${choice==='yes'?'approved':choice==='no'||choice==='change'?'rueckfrage':'soft'}">${choice==='yes'?'ZUGESTIMMT':choice==='no'?'ABGELEHNT':choice==='change'?'ÄNDERUNGSWUNSCH':'AUSSTEHEND'}</span></div>`}).join('')}</div>${v.votes[actor]?.data.comment?`<p class="smalltxt muted">Eigene Rückmeldung: ${rawNotes(v.votes[actor].data.comment)}</p>`:''}<div class="taskBottom"><div class="muted smalltxt">${v.yes}/3 Stimmen · ${esc(t.revision?.id.slice(0,8)||'Version unklar')}</div><div class="btnrow"><button class="btn small" data-request="${esc(t.type+'|'+t.id)}">↗ Anfragen</button><button class="btn small" data-${t.type==='task'?'task':t.type==='material'?'material':'offer'}="${esc(t.id)}">Prüfen & abstimmen →</button></div></div></div>`}).join('')||'<div class="empty">Keine Anträge in dieser Auswahl.</div>'}</div>`}
function renderMaterials(){const arr=E('material');const estimate=arr.reduce((s,e)=>s+Number(e.data?.estimate||0),0);const matcost=events.filter(e=>e.kind==='expense').reduce((s,e)=>s+Number(e.data.amount||0),0);const spendBy=Object.fromEntries(MEMBER_IDS.map(m=>[m,events.filter(e=>e.kind==='expense'&&e.data.payer===m).reduce((s,e)=>s+Number(e.data.amount||0),0)+logsFor(events).filter(e=>e.data.payer===m).reduce((s,e)=>s+Number(e.data.cost||0),0)]));return `${pageHeading('03 / GEMEINSAME BESCHAFFUNG','Material & Auslagen','Vorhandenes zuerst prüfen. Bedarf vor Arbeitsblöcken gemeinsam bündeln; jede Bestellung benötigt 3/3 Freigaben.','<button class="btn primary" data-add-material="1">＋ Material eintragen</button>')}<div class="grid stats" style="margin-bottom:16px"><div class="stat"><div class="statlabel">MATERIALPOSTEN</div><div class="statvalue">${arr.length}</div></div><div class="stat"><div class="statlabel">GEPLANT</div><div class="statvalue" style="font-size:24px">${money(estimate)}</div></div><div class="stat"><div class="statlabel">GEKAUFT</div><div class="statvalue" style="font-size:24px">${money(matcost)}</div></div><div class="stat"><div class="statlabel">ABWEICHUNG</div><div class="statvalue" style="font-size:24px">${money(matcost-estimate)}</div></div></div><div class="panel"><div class="tablewrap"><table class="datatab"><thead><tr><th>Material</th><th>Phase</th><th>Menge</th><th>Budget</th><th>Status</th><th>Freigabe</th><th></th></tr></thead><tbody>${arr.map(e=>{const d=e.data||e.heads[0]?.data||{},v=vote('material',e);return `<tr><td><b>${esc(d.title)}</b><div class="muted">${esc(e.id)} ${d.owned?'· Bereits vorhanden':''}</div></td><td>${esc(d.phase||'–')}</td><td>${num(d.quantity)} ${esc(d.unit||'')}</td><td>${money(d.estimate)}</td><td><span class="pill soft">${esc(materialStatus(events,e.id,d.owned))}</span></td><td>${statusPill(e.conflict?'konflikt':v.state)}</td><td><button class="btn small" data-material="${esc(e.id)}">Öffnen</button></td></tr>`}).join('')}</tbody></table></div></div><div class="sep"><h2>Auslagen nach Mitglied</h2></div><div class="panel"><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(130px,1fr))">${MEMBER_IDS.map(m=>`<div><div class="statlabel">${esc(who(m))}</div><div class="statvalue" style="font-size:23px">${money(spendBy[m])}</div></div>`).join('')}</div></div><div class="sep"><h2>Dokumentierte Einkäufe & Auslagen</h2><button class="btn" data-add-expense="1">＋ Ausgabe erfassen</button></div><div class="panel">${events.filter(e=>e.kind==='expense').length?sortEvents(events.filter(e=>e.kind==='expense')).reverse().map(e=>`<div class="listrow"><div><b>${esc(e.data.title)}</b><p>${niceDate(e.data.date)} · gezahlt von ${esc(who(e.data.payer))} · ${esc(e.data.materialId||'')}</p></div><strong>${money(e.data.amount)}</strong></div>`).join(''):'<p class="muted">Noch keine Einkäufe dokumentiert.</p>'}</div>`}
function renderCalendar(){const list=E('session').sort((a,b)=>(a.data?.date||'').localeCompare(b.data?.date||''));return `${pageHeading('04 / ZUSAMMEN ARBEITEN','Termine & Verfügbarkeit','Gemeinsame Treffen: Montag online, Dienstag und Donnerstag nach Feierabend, Samstag als Hauptarbeitstag. Sonntag nur bei Bedarf.','<button class="btn primary" data-add-session="1">＋ Termin anlegen</button>')}<div class="panel"><h2>Vorgeschlagener Arbeitsrhythmus</h2><div class="rhythm">${RHYTHM.map(r=>`<div class="rhythmrow"><b>${r.day}</b><span>${r.time}</span><span class="muted">${esc(r.work)}</span></div>`).join('')}</div></div><div class="sep"><h2>Termine</h2><span class="muted smalltxt">Startvorlage: 26.10.2026 · Vier Wochen, ohne feste Zusage</span></div><div class="sectionlist">${list.map(s=>{const d=s.data||s.heads[0]?.data||{},rs=latestPerMember(events,'rsvp',s.id);return `<div class="taskCard"><div class="taskTop"><div class="taskbody"><div class="tasknum">${niceDate(d.date)} · ${esc(d.start||'Uhrzeit nach Absprache')}${d.end?'–'+esc(d.end):''}</div><h3>${esc(d.title)}</h3><div class="taskmeta"><span>Woche ${esc(d.week||'–')}: ${esc(d.notes||'')}</span></div></div><span class="pill ${s.conflict?'konflikt':'soft'}">${s.conflict?'KONFLIKT':MEMBER_IDS.filter(m=>rs[m]?.data.choice==='yes').length+'/3 DABEI'}</span></div><div class="taskBottom"><div class="taskmeta">${MEMBER_IDS.map(m=>`${esc(who(m))}: ${rs[m]?.data.choice==='yes'?'✓':rs[m]?.data.choice==='no'?'✕':'?'} `).join(' · ')}</div><button class="btn small" data-session="${esc(s.id)}">Verfügbarkeit →</button></div></div>`}).join('')}</div>`}
function renderLogs(){const work=logsFor(events);const h=hoursFor(events);return `${pageHeading('05 / TÄTIGKEITSNACHWEIS','Arbeitsprotokolle','Nach jedem Arbeitstag: Arbeitsstand, Beteiligte, Dauer, Ergebnisse und Materialbedarf dokumentieren.','<button class="btn primary" data-add-log="1">＋ Arbeit dokumentieren</button>')}<div class="grid stats" style="margin-bottom:18px"><div class="stat"><div class="statlabel">PROTOKOLLE</div><div class="statvalue">${work.length}</div></div><div class="stat"><div class="statlabel">PERSONENSTUNDEN</div><div class="statvalue">${num(h)}</div></div><div class="stat"><div class="statlabel">KALENDERSTUNDEN</div><div class="statvalue">${num(work.reduce((s,e)=>s+Number(e.data.hours||0),0))}</div></div><div class="stat"><div class="statlabel">AUSLAGEN OHNE MATERIAL</div><div class="statvalue" style="font-size:24px">${money(work.reduce((s,e)=>s+Number(e.data.cost||0),0))}</div></div></div>${work.length?work.slice().reverse().map(e=>`<div class="logcard"><div class="listrow" style="padding:0"><div><div class="tasknum">${niceDate(e.data.date)} · ${esc(e.data.taskId)}</div><h3>${esc(findE('task',e.data.taskId)?.data?.title||'Aufgabe')}</h3></div><span class="pill soft">${num(e.data.hours)} h × ${e.data.participants.length} = ${num(e.data.hours*e.data.participants.length)} Ph</span></div><p>${rawNotes(e.data.note||'Kein Kommentar')}</p><div class="taskBottom"><span class="muted smalltxt">${esc(e.data.participants.map(who).join(', '))}${e.data.cost?' · '+money(e.data.cost):''}</span><button class="btn danger small" data-void-log="${esc(e.id)}">Stornieren</button></div></div>`).join(''):'<div class="empty"><b>Noch keine Arbeitsprotokolle</b>Nach dem ersten Termin kann hier der gemeinsame Fortschritt festgehalten werden.</div>'}`}
function renderSync(){const conflicts=conflictingEntities(events);const last=localStorage.getItem('werkstatt-last-import')||'Noch kein Import';const a=names();return `${pageHeading('06 / OFFLINE & DATEIEN','Synchronisieren','Lokale IndexedDB-Daten; Austausch über WhatsApp, E-Mail oder Dateien. Beim Import werden Ereignisse zusammengeführt, nicht pauschal überschrieben.')}<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr));margin-bottom:16px"><section class="panel"><div class="overline">01 / DATEN TEILEN</div><h2 style="margin-top:8px">Änderungsprotokoll</h2><p class="muted smalltxt">Alle bisher bekannten Änderungen als JSON, inklusive bereits importierter Änderungen. Mehrfacher Import ist sicher: IDs werden nur einmal übernommen.</p><div class="btnrow"><button class="btn primary" data-share-log="changes">↗ Protokoll teilen</button><button class="btn" data-export="changes">↓ JSON herunterladen</button></div></section><section class="panel"><div class="overline">02 / SICHERN</div><h2 style="margin-top:8px">Vollständige Sicherung</h2><p class="muted smalltxt">Alle Daten und Einstellungen aus dem Ereignisprotokoll sichern. Vor Gerätewechsel exportieren; Browserdaten können gelöscht werden.</p><button class="btn" data-export="backup">↓ Vollsicherung exportieren</button></section></div><div class="panel" style="margin-bottom:16px"><h2>Privater WhatsApp-Protokollchat</h2><p class="muted smalltxt">Erstellt eine separate WhatsApp-Gruppe <b>WERKSTATT | PROTOKOLLE</b> nur für euch drei. Nach jeder Sitzung <b>Protokoll teilen</b> auswählen, im Teilen-Menü die Gruppe bestimmen und den Versand bestätigen. Alle importieren die neue JSON-Datei vor weiteren Abstimmungen. Ein echter WhatsApp-Kanal ist öffentlich und eignet sich nicht für vertrauliche Projektdateien.</p><div class="notice warn">Kein Hintergrundversand: Die App sendet keine WhatsApp-Nachrichten automatisch. Auf Browsern ohne Datei-Freigabe wird die JSON-Datei heruntergeladen und anschließend als Dokument manuell angehängt.</div></div><div class="panel"><h2>Projektdatei importieren</h2><div class="upload"><strong>JSON-Datei auswählen</strong><p class="muted smalltxt">Änderungen werden anhand eindeutiger IDs geprüft. Bestehende Änderungen bleiben erhalten.</p><input type="file" id="importFile" accept=".json,application/json"><div class="spacing btnrow" style="justify-content:center"><button class="btn primary" id="mergeFile" disabled>↑ Prüfen & zusammenführen</button><button class="btn ghost" id="restoreFile" disabled>Vollsicherung wiederherstellen …</button></div></div><p class="hintline" style="margin-top:12px">Letzter Import: ${esc(last)}</p></div><div class="sep"><h2>Konfliktprüfung</h2><span class="pill ${conflicts.length?'rueckfrage':'approved'}">${conflicts.length} Konflikte</span></div><div class="panel">${conflicts.length?conflicts.map(x=>`<div class="listrow"><div><b>${esc(x.id)}</b><p>${x.type==='task'?'Aufgabe':x.type==='material'?'Material':x.type==='offer'?'Kleinanzeigenangebot':x.type==='session'?'Termin':x.type==='status'?'Bearbeitungsstatus':x.type==='material_status'?'Beschaffungsstatus':'Einzelschritt'} · ${x.heads.length} Änderungsstände${x.missing?.length?', Basis fehlt':''}</p></div><button class="btn small" data-resolve="${esc(x.type+'|'+x.id)}" ${x.missing?.length?'disabled':''}>Auflösen</button></div>`).join(''):'<div class="notice">Keine widersprüchlichen Änderungen entdeckt. Das bedeutet nicht, dass alle Geräte schon dieselben Dateien importiert haben.</div>'}</div><div class="sep"><h2>Mitglieder</h2><span class="muted smalltxt">Gleichberechtigt · Identität auf Vertrauensbasis</span></div><div class="panel"><div class="formgrid">${MEMBER_IDS.map(m=>`<div class="formgroup"><label>${m.toUpperCase()} · Mitglied</label><div class="btnrow"><input class="field" id="name-${m}" value="${esc(a[m])}" maxlength="50" style="flex:1;min-width:100px"><button class="btn small" data-rename="${m}">Speichern</button></div></div>`).join('')}</div><div class="divider"></div><div class="notice warn">Wichtig: Der ausgewählte Name authentifiziert keine Person. Jeder mit der Projektdatei kann die Daten und Stimmen lesen und fälschen. Für sensible Freigaben ist diese Offline-Version kein rechtssicheres Abstimmungssystem.</div><p class="muted smalltxt">Lokale Ereignisse: ${events.length} · Gerätekennung: ${esc(deviceId.slice(0,12))} · Datenformat 1</p></div>`}
function renderOffers(){
 const offers=sortedOffers(events),usable=offers.filter(o=>o.data.availability!=='Nicht verfügbar'),best=usable.length?offerTotal(usable[0].data):0;
 return `${pageHeading('05 / ANGEBOTSVERGLEICH','Kleinanzeigen vergleichen','Links gemeinschaftlich sammeln, Gesamtpreis (Angebot + Versand) vergleichen und eine konkrete Angebotsversion einstimmig freigeben.','<button class="btn primary" data-add-offer="1">＋ Kleinanzeigen-Link erfassen</button>')}
 <div class="notice">Preise, Versand und Verfügbarkeit werden manuell eingegeben. GitHub Pages kann Kleinanzeigen-Daten nicht zuverlässig automatisch auslesen. Alle Angebote werden im JSON-Protokoll mitgeführt.</div>
 <div class="grid stats spacing" style="grid-template-columns:repeat(auto-fit,minmax(160px,1fr))"><div class="stat"><div class="statlabel">GESAMT</div><div class="statvalue">${offers.length}</div></div><div class="stat"><div class="statlabel">GÜNSTIGSTES VERFÜGBARES</div><div class="statvalue" style="font-size:25px">${usable.length?money(best):'–'}</div></div><div class="stat"><div class="statlabel">MIT 3/3 FREIGABE</div><div class="statvalue">${offers.filter(x=>vote('offer',x).state==='approved').length}</div></div></div>
 <div class="sep"><h2>Angebote nach Gesamtkosten</h2><span class="muted smalltxt">Versand / erfasste Fahrtkosten inklusive</span></div>
 <div class="sectionlist">${offers.map((x,i)=>{const d=x.data,v=vote('offer',x);return `<div class="taskCard"><div class="taskTop"><div class="taskbody"><div class="taskmeta"><span class="tasknum">${esc(x.id)}</span><span>${esc(d.materialId||'Ohne Materialzuordnung')}</span>${d.availability==='Nicht verfügbar'?'<span class="pill blocked">NICHT VERFÜGBAR</span>':usable[0]?.id===x.id?'<span class="pill approved">GÜNSTIGSTES ANGEBOT</span>':''}</div><h3>${esc(d.title)}</h3><p class="muted smalltxt">${esc(d.seller||'Verkäufer nicht erfasst')} · Preis ${money(d.price)} + Zusatzkosten ${money(d.shipping)} · ${esc(d.availability)}</p></div><div class="offer-price">${money(offerTotal(d))}</div></div><div class="taskBottom"><div>${statusPill(x.conflict?'konflikt':v.state)}</div><div class="btnrow"><a class="btn small" href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">Anzeige ↗</a><button class="btn small" data-offer="${esc(x.id)}">Vergleichen / abstimmen</button></div></div></div>`}).join('')||'<div class="empty"><b>Noch keine Angebote</b>Den ersten Kleinanzeigen-Link über die Schaltfläche hinzufügen.</div>'}</div>
 <p class="hintline spacing">Hinweis: Ein niedriger Preis bedeutet nicht automatisch einen guten Kauf. Zustand, Seriosität, Fahrtkosten und Verfügbarkeit gemeinsam prüfen.</p>`;
}
function editOffer(id=null,initialMaterialId=''){
 const x=id?findE('offer',id):null;if(x?.conflict){toast('Zuerst Änderungskonflikt lösen.',true);return}
 const d=x?.data||{title:'',url:'',price:0,shipping:0,materialId:initialMaterialId,seller:'',availability:'Angeboten',notes:''};
 openModal(id?'Kleinanzeigenangebot bearbeiten':'Kleinanzeigen-Link hinzufügen',`<form id="editForm" data-form="offer" data-id="${esc(id||'')}"><div class="notice">Kosten als Zahlen eingeben. Die Summe wird automatisch sortiert. Änderungen an Link, Angebot oder Preis erfordern eine neue 3/3-Zustimmung.</div><div class="formgrid spacing"><div class="formgroup full"><label>HTTPS-Link zu Kleinanzeigen *</label><input class="field" required type="url" name="url" placeholder="https://www.kleinanzeigen.de/s-anzeige/..." value="${esc(d.url)}"></div><div class="formgroup full"><label>Bezeichnung *</label><input class="field" maxlength="160" name="title" required value="${esc(d.title)}"></div><div class="formgroup"><label>Angebotspreis (€)</label><input class="field" name="price" type="number" min="0" step="0.01" required value="${Number(d.price)}"></div><div class="formgroup"><label>Versand / Fahrt (€)</label><input class="field" name="shipping" type="number" min="0" step="0.01" required value="${Number(d.shipping)}"></div><div class="formgroup full"><label>Zugehöriger Materialposten</label><select class="field" name="materialId"><option value="">Ohne Zuordnung</option>${E('material').filter(m=>m.data).map(m=>`<option value="${esc(m.id)}" ${d.materialId===m.id?'selected':''}>${esc(m.id+' · '+m.data.title)}</option>`).join('')}</select></div><div class="formgroup"><label>Verkäufer / Ort</label><input class="field" name="seller" maxlength="100" value="${esc(d.seller)}"></div><div class="formgroup"><label>Verfügbarkeit</label><select class="field" name="availability">${['Angeboten','Reserviert','Nicht verfügbar'].map(x=>`<option ${d.availability===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="formgroup full"><label>Notizen, Zustand, Fahrtkosten, Risiken</label><textarea class="field" name="notes">${esc(d.notes)}</textarea></div></div><div class="modal-actions"><button class="btn ghost" type="button" data-close="1">Abbrechen</button><button class="btn primary" type="submit">Angebot speichern & Freigabe einholen</button></div></form>`);
}
function detailOffer(id){const x=findE('offer',id);if(!x)return;const d=x.data||x.heads[0]?.data||{};openModal(`${id} · ${d.title}`,`<div class="taskmeta">${esc(d.materialId||'Ohne Materialposten')} · ${esc(d.availability||'')}</div><div class="grid stats spacing" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="stat"><div class="statlabel">PREIS</div><div class="statvalue" style="font-size:22px">${money(d.price)}</div></div><div class="stat"><div class="statlabel">INKL. VERSAND</div><div class="statvalue" style="font-size:22px">${money(offerTotal(d))}</div></div></div><p class="muted smalltxt">${esc(d.seller||'Kein Verkäufer erfasst')} · ${rawNotes(d.notes||'Keine Notizen')}</p><p><a class="btn" href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">Originalanzeige öffnen ↗</a></p><div class="divider"></div>${voteButtons('offer',x)}<div class="divider"></div><button class="btn" data-edit-offer="${esc(id)}">✎ Angebot / Preis ändern</button>`)}
function approvalHash(req){return '#approval='+encodeURIComponent(JSON.stringify(req))}
function reqLink(type,x,to){return location.href.split('#')[0]+approvalHash(approvalRequest(type,x,to))}
function approvalMessage(type,x,to){const d=x.data;const moneyPart=type==='task'?`Zeit: ${num(d.calendarHours)} h / ${num(d.personHours)} Personen-h\nKostenbudget: ${money(d.budget)}`:type==='material'?`Kostenbudget: ${money(d.estimate)}`:`Angebot inkl. Versand: ${money(offerTotal(d))}`;return `WERKSTATT | FREIGABEANFRAGE\nAn: ${who(to)}\n${type==='task'?'Aufgabe':type==='material'?'Material':'Kleinanzeige'}: ${x.id} – ${d.title}\n${moneyPart}\nVersion: ${x.revision.id}\n\nPrüfen und abstimmen:\n${reqLink(type,x,to)}\n\nFalls die Version nicht vorliegt: Zuerst die neueste JSON-Datei aus der privaten Protokollgruppe importieren. Danach die Entscheidung als JSON zurückteilen. Keine automatische Übermittlung.`}
function showSendApproval(type,id){const x=findE(type,id);if(!x||x.conflict||!x.revision)throw new Error('Nur eindeutige, aktuelle Versionen können versendet werden.');const v=vote(type,x);openModal('Freigabeanfrage senden',`<p class="muted">${esc(x.data.title)} · ${esc(x.id)} · Revision ${esc(x.revision.id.slice(0,14))}</p><div class="notice">Der Link öffnet die Prüfung in der App. Die Empfänger benötigen den gleichen aktuellen Datenstand. WhatsApp wird geöffnet, du wählst den Kontakt aus und bestätigst den Versand selbst.</div><div class="voters spacing">${MEMBER_IDS.map(m=>`<div class="voter"><div><strong>${esc(who(m))}</strong><div class="smalltxt muted">${v.votes[m]?.data.choice==='yes'?'Bereits zugestimmt':v.votes[m]?.data.choice==='no'?'Abgelehnt':v.votes[m]?.data.choice==='change'?'Änderung angefragt':'Zustimmung ausstehend'}</div></div><div class="btnrow"><button class="btn small" data-copy-request="${esc(type+'|'+id+'|'+m)}">Kopieren</button><button class="btn primary small" data-send-request="${esc(type+'|'+id+'|'+m)}">↗ WhatsApp</button></div></div>`).join('')}</div><p class="muted smalltxt spacing">Die Freigabe ist erst vollständig, wenn alle 3 aktuellen Zustimmungen über JSON zusammengeführt wurden. Anfragen sind keine rechtssicheren elektronischen Signaturen.</p>`)}
async function copyRequest(type,id,to){const x=findE(type,id);if(!x?.revision)throw new Error('Aufgabe nicht vorhanden.');await navigator.clipboard.writeText(approvalMessage(type,x,to));toast('Freigabeanfrage kopiert.');}
async function sendApproval(type,id,to){const x=findE(type,id);if(!x?.revision)throw new Error('Vorhaben nicht vorhanden.');const message=approvalMessage(type,x,to);window.open('https://wa.me/?text='+encodeURIComponent(message),'_blank','noopener,noreferrer');toast('WhatsApp geöffnet. Empfänger wählen und Nachricht absenden.');}
function showApprovalRequest(){let request;try{request=JSON.parse(decodeURIComponent(location.hash.slice('#approval='.length)))}catch{toast('Ungültiger Freigabelink.',true);return}
 if(!request||!['task','material','offer'].includes(request.type)||!MEMBER_IDS.includes(request.to)||typeof request.id!=='string'||typeof request.revisionId!=='string'){toast('Freigabeanfrage ungültig.',true);return}
 const x=findE(request.type,request.id),ok=checkApprovalRequest(request,x);page='votes';render();
 if(!ok){openModal('Freigabeanfrage · Import erforderlich',`<div class="notice warn"><b>Die angefragte Version liegt hier nicht vor.</b> ${esc(request.id)} · ${esc(request.revisionId.slice(0,14))}</div><p>Importiere zuerst das aktuelle Änderungsprotokoll aus eurer privaten WhatsApp-Protokollgruppe. Danach denselben Freigabelink erneut öffnen. Alte oder widersprüchliche Versionen dürfen nicht freigegeben werden.</p><button class="btn primary" data-open-sync="1">Zum JSON-Import</button>`);return}
 if(actor!==request.to){openModal('Freigabeanfrage für '+who(request.to),`<p>Dieser Link ist adressiert an <strong>${esc(who(request.to))}</strong>. Aktuell ausgewählt: ${esc(who(actor))}.</p><div class="notice warn">Identität auf Vertrauensbasis. Bitte nur das eigene Profil auswählen.</div><button class="btn primary spacing" data-approval-actor="${request.to}">Als ${esc(who(request.to))} prüfen</button>`);return}
 const d=x.data;openModal('Freigabeprüfung · '+x.id,`<div class="eyebrow accent">ANTRAG · ${esc(x.revision.id.slice(0,14))}</div><h2>${esc(d.title)}</h2><p class="muted">${request.type==='task'?`Zeitbudget ${num(d.calendarHours)} h / ${num(d.personHours)} Personenstunden · Kostenrahmen ${money(d.budget)}`:request.type==='material'?`Materialbudget ${money(d.estimate)} · Menge ${num(d.quantity)}`:`Kleinanzeigenpreis ${money(d.price)} · Versand ${money(d.shipping)} · Gesamt ${money(offerTotal(d))}`}</p>${request.type==='task'?`<div class="checklist">${d.steps.map(q=>`<div class="checkitem">${esc(q)}</div>`).join('')}</div>`:request.type==='offer'?`<p><a class="btn" href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">Originalanzeige prüfen ↗</a></p>`:''}${request.type==='task'?`<div class="notice">Raum: ${esc(d.room)} · Zuständig: ${esc(d.assignees.map(who).join(', '))} · Fällig: ${niceDate(d.due)}</div>`:''}${d.notes?`<p class="muted">Notizen: ${rawNotes(d.notes)}</p>`:''}${request.type==='material'?`<p>Beschaffungsphase: ${esc(d.phase||'–')} · Raum: ${esc(d.room||'–')}</p>`:''}${request.type==='offer'?`<p>Verkäufer / Ort: ${esc(d.seller||'nicht angegeben')} · Verfügbarkeit: ${esc(d.availability)}</p>`:''}<div class="divider"></div>${voteButtons(request.type,x)}<p class="muted smalltxt">Nach Abstimmung: Unter Synchronisieren → Protokoll direkt teilen. Ohne importierte Rückmeldungen der anderen ist die Freigabe nicht vollständig.</p>`);
}
async function shareLog(type){const stamp=new Date().toISOString().slice(0,16).replaceAll(':','-'),filename=`MAAK-${type==='backup'?'Vollsicherung':'Protokoll'}-${stamp}.json`,payload=JSON.stringify(transfer(events,type,deviceId),null,2),file=new File([payload],filename,{type:'application/json'});
 if(navigator.share&&navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'WERKSTATT · Protokoll',text:'Projektabgleich – bitte diese JSON-Datei in die Werkstatt-App importieren. Nur in unserer privaten WhatsApp-Protokollgruppe teilen.'});toast('Teilen-Menü geschlossen. Versand bitte in WhatsApp prüfen.');return}catch(err){if(err?.name==='AbortError')return;}}
 downloadFile(filename,payload);toast('JSON heruntergeladen. Bitte als Dokument in der privaten Protokollgruppe teilen.');
}

function openModal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=`<div class="modal-body">${html}</div>`;$('#modal').classList.remove('hidden');document.body.style.overflow='hidden';$('#modalBody').querySelector('input,button,select')?.focus()}
function closeModal(){$('#modal').classList.add('hidden');document.body.style.overflow=''}
function voteButtons(type,t){if(t.conflict)return '<div class="notice error">Nicht abstimmbar: zuerst Änderungskonflikt im Modul „Synchronisieren“ klären.</div>';const v=vote(type,t),mine=v.votes[actor]?.data;return `<section><h3>Verbindliche Projektabstimmung</h3><div class="voters">${MEMBER_IDS.map(m=>{let choice=v.votes[m]?.data.choice;let c=v.votes[m]?.data.comment;return `<div class="voter"><span class="who">${esc(who(m))}</span><div style="text-align:right"><span class="pill ${choice==='yes'?'approved':choice==='no'||choice==='change'?'rueckfrage':'soft'}">${choice==='yes'?'Zustimmung':choice==='no'?'Abgelehnt':choice==='change'?'Änderungswunsch':'Ausstehend'}</span>${c?`<div class="muted smalltxt">${esc(c)}</div>`:''}</div></div>`}).join('')}</div><div class="spacing notice ${v.state==='approved'?'':'warn'}">${v.state==='approved'?'✓ Einstimmig freigegeben.':v.state==='rueckfrage'?'Vorhaben gesperrt – Anpassung und erneute Abstimmung erforderlich.':'Noch nicht freigegeben – '+v.yes+' von 3 Zustimmungen.'} ${mine?'Deine aktuelle Stimme: '+(mine.choice==='yes'?'Zustimmung':mine.choice==='no'?'Ablehnung':'Änderungsvorschlag')+'.':''}</div><div class="voteopts spacing"><button class="btn yes" data-cast="${esc(type+'|'+t.id+'|yes')}">✓ Zustimmen</button><button class="btn change" data-cast="${esc(type+'|'+t.id+'|change')}">✎ Änderung vorschlagen</button><button class="btn no" data-cast="${esc(type+'|'+t.id+'|no')}">✕ Ablehnen</button></div><div class="btnrow spacing"><button class="btn primary" data-request="${esc(type+'|'+t.id)}">↗ Approval an Mitglieder senden</button>${mine?'<button class="btn" data-share-log="changes">↗ Stimme als JSON teilen</button>':''}</div><p class="muted smalltxt">Deine Stimme kann geändert werden. Stimmen gelten nur für diese Version; eine neue Version fordert alle drei Stimmen erneut.</p></section>`}
function detailTask(id){const t=findE('task',id);if(!t)return;const d=t.data||t.heads[0]?.data||{};const v=vote('task',t),s=taskStats(events,t),actual=hoursFor(events,id),cash=costsFor(events,id),enabled=v.state==='approved'&&!t.conflict;const stepUI=(d.steps||[]).map((a,i)=>{let st=stepState(events,id,i);return `<label class="checkitem ${st.done?'done':''}"><input type="checkbox" data-step="${esc(id)}|${i}" ${st.done?'checked':''} ${enabled&&!st.conflict?'':'disabled'}><span class="checklabel">${esc(a)}</span>${st.conflict?'<span class="pill konflikt">KONFLIKT</span>':''}</label>`}).join('');openModal(`${id} · ${d.title}`,`<div class="taskmeta"><span>${esc(groupFor(t))}</span><span>${esc(d.room)}</span><span>Woche ${esc(d.week||'–')}</span>${d.expert?'<span class="pill info">FACHPERSON ERFORDERLICH</span>':''}</div><div class="spacing">${statusPill(t.conflict?'konflikt':v.state)}</div><div class="grid stats spacing" style="grid-template-columns:repeat(2,1fr)"><div class="stat"><div class="statlabel">KALENDERDAUER</div><div class="statvalue" style="font-size:23px">${num(d.calendarHours||0)} h</div></div><div class="stat"><div class="statlabel">PERSONENSTUNDEN PLAN / IST</div><div class="statvalue" style="font-size:23px">${num(d.personHours||0)} / ${num(actual)}</div></div><div class="stat"><div class="statlabel">BUDGET</div><div class="statvalue" style="font-size:23px">${money(d.budget)}</div></div><div class="stat"><div class="statlabel">AUSGABEN IST</div><div class="statvalue" style="font-size:23px">${money(cash)}</div></div></div><div class="spacing muted smalltxt">Koordination: ${esc((d.assignees||[]).map(who).join(', ')||'nicht vergeben')} · Fällig: ${niceDate(d.due)}</div>${d.notes?`<p>${rawNotes(d.notes)}</p>`:''}${d.expert?'<div class="notice warn">Fachprüfung bzw. fachgerechte Ausführung erforderlich. Die 3/3-Zustimmung ersetzt weder den Vermieter noch notwendige fachliche oder behördliche Freigaben.</div>':''}<div class="sep"><h2>Einzelmaßnahmen</h2><span class="badgecount">${s.done}/${s.total} erledigt</span></div>${enabled?'':'<div class="notice warn" style="margin-bottom:10px">Abhaken erst nach Freigabe der aktuellen Aufgabenfassung möglich.</div>'}<div class="checklist">${stepUI||'<p class="muted">Keine Teilschritte hinterlegt.</p>'}</div><div class="sep"><h2>Bearbeitungsstatus</h2></div><div class="btnrow"><select class="field" id="taskState" style="flex:1" aria-label="Bearbeitungsstatus"><option ${recentStatus(events,id)==='Offen'?'selected':''}>Offen</option><option ${recentStatus(events,id)==='Material fehlt'?'selected':''}>Material fehlt</option><option ${recentStatus(events,id)==='In Arbeit'?'selected':''}>In Arbeit</option><option ${recentStatus(events,id)==='Blockiert'?'selected':''}>Blockiert</option></select><button class="btn" data-status="${esc(id)}">Status speichern</button></div><div class="muted smalltxt spacing">Alle Einzelschritte abgeschlossen = automatisch „Erledigt“. Eine noch ausstehende Freigabe sperrt die Ausführung.</div><div class="divider"></div>${voteButtons('task',t)}<div class="divider"></div><div class="btnrow"><button class="btn" data-edit-task="${esc(id)}">✎ Umfang / Budgets bearbeiten</button><button class="btn" data-log-task="${esc(id)}" ${enabled?'':'disabled'}>＋ Arbeitsnachweis</button></div>`)}
function editTask(id=null){const t=id?findE('task',id):null;if(t?.conflict){toast('Zuerst den Änderungskonflikt auflösen.',true);return}const d=t?.data||{title:'',section:'P1',room:'Alle Räume',week:1,priority:'normal',assignees:['a','b','c'],calendarHours:0,personHours:0,budget:0,due:'',notes:'',expert:false,steps:[]};openModal(id?'Arbeitspaket bearbeiten':'Neues Vorhaben',`<form id="editForm" data-form="task" data-id="${esc(id||'')}"><div class="notice warn">Änderungen an Inhalt, Zuordnung oder Budget erzeugen eine neue Version. Die Zustimmung aller drei Mitglieder ist erneut erforderlich.</div><div class="formgrid spacing"><div class="formgroup full"><label>Titel *</label><input class="field" name="title" required maxlength="160" value="${esc(d.title)}"></div><div class="formgroup"><label>Prioritätsphase</label><select class="field" name="section">${SECTIONS.map(s=>`<option value="${s.id}" ${s.id===d.section?'selected':''}>${esc(s.id+' · '+s.title)}</option>`).join('')}</select></div><div class="formgroup"><label>Raum</label><select class="field" name="room">${['Alle Räume','Raum 1','Hauptwerkstatt','Raum 3','Außenbereich'].map(s=>`<option ${d.room===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="formgroup"><label>Planwoche (Orientierung)</label><input class="field" type="number" name="week" min="1" max="99" value="${d.week||1}"></div><div class="formgroup"><label>Fälligkeit (optional)</label><input class="field" type="date" name="due" value="${esc(d.due)}"></div><div class="formgroup"><label>Kalenderdauer (h)</label><input class="field" type="number" name="calendarHours" step="0.25" min="0" value="${d.calendarHours||0}"></div><div class="formgroup"><label>Zeitbudget (Personenstunden)</label><input class="field" type="number" name="personHours" step="0.25" min="0" value="${d.personHours||0}"></div><div class="formgroup"><label>Kostenbudget (€)</label><input class="field" type="number" name="budget" step="0.01" min="0" value="${d.budget||0}"></div><div class="formgroup"><label>Priorität</label><select class="field" name="priority"><option value="normal" ${d.priority==='normal'?'selected':''}>Normal</option><option value="hoch" ${d.priority==='hoch'?'selected':''}>Hoch</option><option value="kritisch" ${d.priority==='kritisch'?'selected':''}>Kritisch</option></select></div><div class="formgroup full"><label>Koordination / Beteiligte (keine festen Gewerke)</label><div class="memberChecks">${MEMBER_IDS.map(m=>`<label><input type="checkbox" name="assignee" value="${m}" ${(d.assignees||[]).includes(m)?'checked':''}> ${esc(who(m))}</label>`).join('')}</div></div><div class="formgroup full"><label>Beschreibung / Hinweise</label><textarea class="field" name="notes">${esc(d.notes||'')}</textarea></div><div class="formgroup full"><label>Einzelmaßnahmen – eine Zeile pro Schritt</label><textarea class="field" name="steps" rows="${Math.max(3,Math.min(9,(d.steps||[]).length+1))}">${esc((d.steps||[]).join('\n'))}</textarea><div class="fieldhint">Vorhandene Schritte nicht löschen, um bereits dokumentierten Fortschritt nicht zu verändern. Neue Schritte können unten ergänzt werden.</div></div><div class="formgroup full"><label class="checkboxline"><input type="checkbox" name="expert" ${d.expert?'checked':''}> Fachprüfung oder fachkundige Ausführung erforderlich</label></div></div><div class="modal-actions"><button type="button" class="btn ghost" data-close="1">Abbrechen</button><button class="btn primary" type="submit">Neue Fassung zur Abstimmung stellen</button></div></form>`)}
function detailMaterial(id){const t=findE('material',id);if(!t)return;const d=t.data||t.heads[0]?.data||{},v=vote('material',t);const paid=events.filter(e=>e.kind==='expense'&&e.data.materialId===id).reduce((s,e)=>s+e.data.amount,0);openModal(`${id} · ${d.title}`,`<div class="taskmeta"><span>${esc(d.phase||'')}</span><span>${esc(d.room||'')}</span>${d.owned?'<span class="pill approved">BEREITS VORHANDEN</span>':''}</div><div class="spacing">${statusPill(t.conflict?'konflikt':v.state)}</div><div class="grid stats spacing" style="grid-template-columns:repeat(2,1fr)"><div class="stat"><div class="statlabel">MENGE</div><div class="statvalue" style="font-size:24px">${num(d.quantity||0)} ${esc(d.unit||'')}</div></div><div class="stat"><div class="statlabel">BUDGET / IST</div><div class="statvalue" style="font-size:24px">${money(d.estimate)} / ${money(paid)}</div></div></div><p class="muted">Einkauf: ${d.buyer?esc(who(d.buyer)):'gemeinsam abzustimmen'} · ${d.taskId?'Verknüpft mit '+esc(d.taskId)+' · ':''}${rawNotes(d.notes||'Keine Notizen')}</p><div class="sep"><h2>Beschaffungsstatus</h2></div><div class="btnrow"><select class="field" id="materialState" style="flex:1">${['Bedarf','Geplant','Bestellt','Beschafft','Vorhanden'].map(st=>`<option ${materialStatus(events,id,d.owned)===st?'selected':''}>${st}</option>`).join('')}</select><button class="btn" data-mat-status="${esc(id)}">Status speichern</button></div><div class="divider"></div><div class="sep"><h2>Kleinanzeigen-Angebote</h2><button class="btn small" data-add-offer="${esc(id)}">＋ Angebot hinzufügen</button></div>${sortedOffers(events,id).map((o,i)=>`<div class="listrow"><div><b>${i+1}. ${esc(o.data.title)}</b><p>${money(o.data.price)} + ${money(o.data.shipping)} Zusatzkosten · ${esc(o.data.availability)}</p></div><div class="btnrow"><strong>${money(offerTotal(o.data))}</strong><button class="btn small" data-offer="${esc(o.id)}">Details</button></div></div>`).join('')||'<p class="muted smalltxt">Noch keine verknüpften Kleinanzeigen-Angebote.</p>'}<div class="divider"></div>${voteButtons('material',t)}<div class="divider"></div><div class="btnrow"><button class="btn" data-edit-material="${esc(id)}">✎ Materialposten bearbeiten</button><button class="btn" data-buy-material="${esc(id)}" ${v.state==='approved'&&!d.owned?'':'disabled'}>＋ Kauf / Beleg erfassen</button></div>`)}
function editMaterial(id=null){const t=id?findE('material',id):null;if(t?.conflict){toast('Konflikt zuerst auflösen.',true);return}const d=t?.data||{title:'',phase:'Vor Arbeitsbeginn',quantity:1,unit:'Stück',estimate:0,buyer:'',taskId:'',room:'Alle Räume',notes:'',owned:false};openModal(id?'Materialposten bearbeiten':'Material vorschlagen',`<form id="editForm" data-form="material" data-id="${esc(id||'')}"><div class="notice warn">Beschaffung nur nach einstimmiger Freigabe der aktuellen Menge und des Budgets.</div><div class="formgrid spacing"><div class="formgroup full"><label>Materialbezeichnung *</label><input class="field" name="title" maxlength="160" required value="${esc(d.title)}"></div><div class="formgroup full"><label>Beschaffungsrunde</label><select class="field" name="phase">${[...new Set(Object.values(allSeeds.material).map(x=>x.phase)),'Sonstiges'].map(x=>`<option ${d.phase===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="formgroup"><label>Menge</label><input class="field" type="number" name="quantity" min="0" step="0.01" value="${d.quantity}"></div><div class="formgroup"><label>Einheit</label><input class="field" name="unit" maxlength="30" value="${esc(d.unit)}"></div><div class="formgroup"><label>Budget (€)</label><input class="field" type="number" name="estimate" min="0" step="0.01" value="${d.estimate}"></div><div class="formgroup"><label>Einkaufskoordination</label><select class="field" name="buyer"><option value="">Gemeinsam / offen</option>${MEMBER_IDS.map(m=>`<option value="${m}" ${d.buyer===m?'selected':''}>${esc(who(m))}</option>`).join('')}</select></div><div class="formgroup"><label>Raum</label><select class="field" name="room">${['Alle Räume','Raum 1','Hauptwerkstatt','Raum 3','Außenbereich'].map(x=>`<option ${d.room===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="formgroup full"><label>Zugehöriges Arbeitspaket (optional)</label><select class="field" name="taskId"><option value="">Keine feste Zuordnung</option>${E('task').filter(t=>t.data).map(t=>`<option value="${esc(t.id)}" ${d.taskId===t.id?'selected':''}>${esc(t.id+' · '+t.data.title)}</option>`).join('')}</select><div class="fieldhint">Verknüpfte Materialausgaben zählen auch zum Aufgabenbudget; sie werden in der Gesamtsumme nicht doppelt gezählt.</div></div><div class="formgroup full"><label>Bemerkungen / Bezugsquelle / Belegverweis</label><textarea class="field" name="notes">${esc(d.notes)}</textarea></div><div class="formgroup full"><label class="checkboxline"><input type="checkbox" name="owned" ${d.owned?'checked':''}> Bereits vorhanden / kein Einkauf erforderlich</label></div></div><div class="modal-actions"><button type="button" class="btn ghost" data-close="1">Abbrechen</button><button class="btn primary" type="submit">Zur Abstimmung stellen</button></div></form>`)}
function detailSession(id){const t=findE('session',id);if(!t)return;const d=t.data||t.heads[0]?.data||{},rs=latestPerMember(events,'rsvp',id);openModal('Termin · '+d.title,`<p class="muted">${niceDate(d.date)} · ${esc(d.start||'Uhrzeit offen')}${d.end?'–'+esc(d.end):''} · ${esc(d.notes||'')}</p><h3>Wer ist dabei?</h3><div class="voters spacing">${MEMBER_IDS.map(m=>`<div class="voter"><span>${esc(who(m))}</span><span class="pill ${rs[m]?.data.choice==='yes'?'approved':rs[m]?.data.choice==='no'?'rueckfrage':'soft'}">${rs[m]?.data.choice==='yes'?'Dabei':rs[m]?.data.choice==='no'?'Nicht verfügbar':'Noch offen'}</span></div>`).join('')}</div><div class="btnrow spacing"><button class="btn primary" data-rsvp="${esc(id)}|yes">✓ Ich bin dabei</button><button class="btn" data-rsvp="${esc(id)}|no">✕ Nicht verfügbar</button><button class="btn" data-rsvp="${esc(id)}|maybe">? Noch unklar</button></div><div class="divider"></div><button class="btn" data-edit-session="${esc(id)}">✎ Termin bearbeiten</button>`)}
function editSession(id=null){const t=id?findE('session',id):null;if(t?.conflict){toast('Konflikt zuerst auflösen.',true);return}const d=t?.data||{title:'Gemeinsamer Werkstatttermin',date:new Date().toISOString().slice(0,10),start:'',end:'',notes:'',kind:'werkstatt',week:1};openModal(id?'Termin bearbeiten':'Neuer Termin',`<form id="editForm" data-form="session" data-id="${esc(id||'')}"><div class="formgrid"><div class="formgroup full"><label>Bezeichnung *</label><input class="field" name="title" required maxlength="160" value="${esc(d.title)}"></div><div class="formgroup"><label>Datum</label><input class="field" type="date" name="date" required value="${esc(d.date)}"></div><div class="formgroup"><label>Planwoche</label><input class="field" type="number" min="1" name="week" value="${d.week||1}"></div><div class="formgroup"><label>Beginn (optional)</label><input class="field" type="time" name="start" value="${esc(d.start)}"></div><div class="formgroup"><label>Ende (optional)</label><input class="field" type="time" name="end" value="${esc(d.end)}"></div><div class="formgroup full"><label>Hinweise</label><textarea class="field" name="notes">${esc(d.notes)}</textarea></div></div><div class="modal-actions"><button type="button" class="btn" data-close="1">Abbrechen</button><button class="btn primary" type="submit">Termin speichern</button></div></form>`)}
function newWorklog(taskId=null){const choices=E('task').filter(t=>vote('task',t).state==='approved');if(!choices.length){toast('Erst mindestens ein Arbeitspaket einstimmig freigeben.',true);return}const d=taskId||choices[0].id;openModal('Arbeitsprotokoll erfassen',`<form id="editForm" data-form="worklog"><div class="formgrid"><div class="formgroup full"><label>Freigegebenes Arbeitspaket</label><select class="field" name="taskId">${choices.map(t=>`<option value="${esc(t.id)}" ${d===t.id?'selected':''}>${esc(t.id+' · '+t.data.title)}</option>`).join('')}</select></div><div class="formgroup"><label>Arbeitstag</label><input class="field" type="date" name="date" required value="${new Date().toISOString().slice(0,10)}"></div><div class="formgroup"><label>Kalenderdauer in Stunden</label><input class="field" type="number" min="0.25" max="24" step="0.25" name="hours" value="2" required><span class="fieldhint">Personenstunden = Dauer × Anzahl Anwesender</span></div><div class="formgroup full"><label>Beteiligte</label><div class="memberChecks">${MEMBER_IDS.map(m=>`<label><input type="checkbox" name="participant" value="${m}" ${m===actor?'checked':''}>${esc(who(m))}</label>`).join('')}</div></div><div class="formgroup"><label>Zusätzliche Auslagen (€)</label><input class="field" type="number" min="0" step="0.01" name="cost" value="0"><span class="fieldhint">Materialkäufe stattdessen im Materialmodul buchen, sonst doppelte Kosten.</span></div><div class="formgroup"><label>Bezahlt von</label><select class="field" name="payer"><option value="">Keine Auslage</option>${MEMBER_IDS.map(m=>`<option ${m===actor?'selected':''} value="${m}">${esc(who(m))}</option>`).join('')}</select></div><div class="formgroup full"><label>Ergebnis, Fortschritt, Hindernisse / Material für den nächsten Tag</label><textarea class="field" name="note" required placeholder="Was wurde geschafft? Was ist als Nächstes zu tun?"></textarea></div></div><div class="modal-actions"><button class="btn" type="button" data-close="1">Abbrechen</button><button class="btn primary" type="submit">Protokoll speichern</button></div></form>`)}
function newExpense(matId=null){const mats=E('material').filter(m=>vote('material',m).state==='approved'&&!m.data.owned);if(!mats.length){toast('Zuerst mindestens einen Materialposten freigeben.',true);return}const selected=matId&&mats.find(x=>x.id===matId)?matId:mats[0].id;openModal('Materialkauf / Auslage dokumentieren',`<form id="editForm" data-form="expense"><div class="formgrid"><div class="formgroup full"><label>Freigegebener Materialposten</label><select class="field" name="materialId">${mats.map(t=>`<option value="${esc(t.id)}" ${t.id===selected?'selected':''}>${esc(t.id+' · '+t.data.title)}</option>`).join('')}</select></div><div class="formgroup full"><label>Bezeichnung</label><input class="field" required name="title" value="${esc(mats.find(x=>x.id===selected)?.data?.title||'')}"></div><div class="formgroup"><label>Belegdatum</label><input class="field" name="date" type="date" required value="${new Date().toISOString().slice(0,10)}"></div><div class="formgroup"><label>Bezahlter Betrag (€)</label><input class="field" name="amount" type="number" min="0.01" step="0.01" required></div><div class="formgroup"><label>Bezahlt von</label><select class="field" name="payer">${MEMBER_IDS.map(m=>`<option value="${m}" ${m===actor?'selected':''}>${esc(who(m))}</option>`).join('')}</select></div><div class="formgroup full"><label>Freigegebenes Kleinanzeigenangebot (optional)</label><select class="field" name="offerId"><option value="">Kein konkretes Angebot zuordnen</option>${sortedOffers(events).filter(o=>o.data.materialId===selected&&o.data.availability!=='Nicht verfügbar'&&vote('offer',o).state==='approved').map(o=>`<option value="${esc(o.id)}">${esc(o.title||o.data.title)} · ${money(offerTotal(o.data))} · ${esc(o.data.materialId||'Ohne Materialbezug')}</option>`).join('')}</select><span class="fieldhint">Nur 3/3-freigegebene Angebote. Das verknüpfte Material muss ebenfalls freigegeben sein.</span></div><div class="formgroup full"><label>Belegreferenz / Hinweis</label><textarea class="field" name="note" placeholder="z.B. Beleg_2026-10-31.jpg – Foto bitte separat aufbewahren"></textarea></div></div><div class="modal-actions"><button class="btn" type="button" data-close="1">Abbrechen</button><button class="btn primary" type="submit">Ausgabe protokollieren</button></div></form>`)}
function showResolve(type,id){const x=entityHeads(events,type,id);if(!x.conflict||x.missing.length){toast('Für die Auflösung fehlen Basisänderungen oder kein Konflikt vorhanden.',true);return}openModal('Konflikt lösen · '+id,`<div class="notice warn">${x.heads.length} parallele Versionen. Wähle die verbindliche Fassung. Daraus entsteht eine neue Revision; bisherige Stimmen verlieren ihre Gültigkeit. Anschließend kann die Fassung normal bearbeitet werden.</div><div class="sectionlist spacing">${x.heads.map(h=>`<div class="taskCard"><div class="tasknum">ÄNDERUNG ${esc(h.id.slice(0,12))} · ${esc(h.by?who(h.by):'Vorlage')}</div><h3>${type==='step'?(h.data.done?'Schritt erledigt':'Schritt offen'):type==='status'||type==='material_status'?esc(h.data.status):esc(h.data.title)}</h3>${type!=='step'?`<pre style="font-size:11px;white-space:pre-wrap;overflow:auto;max-height:190px;color:#b5c9bf">${esc(JSON.stringify(h.data,null,2))}</pre>`:''}<button class="btn" data-resolve-choice="${esc(type+'|'+id+'|'+h.id)}">Diese Fassung übernehmen</button></div>`).join('')}</div>`)}
async function saveForm(f){const kind=f.dataset.form,id=f.dataset.id||null;let data,ev;
 if(kind==='task'){
  const old=id?findE('task',id)?.data:null;
  const steps=formVal(f,'steps').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,150);
  if(!steps.length)throw new Error('Mindestens ein Einzelschritt ist erforderlich.');
  if(old&&old.steps.some((x,i)=>steps[i]!==x))throw new Error('Bestehende Schritte dürfen nicht gelöscht oder umsortiert werden. Neue Schritte bitte unten anhängen.');
  const assignees=[...f.querySelectorAll('[name=assignee]:checked')].map(x=>x.value);
  if(!assignees.length)throw new Error('Mindestens ein koordinierendes Mitglied auswählen.');
  data={id:id||'WS-'+uid().slice(0,8).toUpperCase(),title:formVal(f,'title').trim(),section:formVal(f,'section'),week:Math.max(1,formNum(f,'week')),room:formVal(f,'room'),priority:formVal(f,'priority'),assignees,calendarHours:formNum(f,'calendarHours'),personHours:formNum(f,'personHours'),budget:formNum(f,'budget'),due:formVal(f,'due'),notes:formVal(f,'notes').slice(0,3000),expert:!!f.elements.namedItem('expert').checked,steps};
  if(data.title.length<3)throw new Error('Aufgabentitel zu kurz.');
  if(old&&JSON.stringify(data)===JSON.stringify(old)){toast('Keine Änderungen vorhanden.');closeModal();return}
  ev=eventOf('task_revision',data.id,data,id?headParent('task',id):[]);
 }else if(kind==='material'){
  data={id:id||'MAT-'+uid().slice(0,8).toUpperCase(),title:formVal(f,'title').trim(),phase:formVal(f,'phase'),quantity:formNum(f,'quantity'),unit:formVal(f,'unit').slice(0,30),estimate:formNum(f,'estimate'),buyer:formVal(f,'buyer'),taskId:formVal(f,'taskId'),room:formVal(f,'room'),notes:formVal(f,'notes').slice(0,3000),owned:!!f.elements.namedItem('owned').checked};
  if(data.title.length<3)throw new Error('Bezeichnung zu kurz.');
  if(id&&JSON.stringify(data)===JSON.stringify(findE('material',id).data)){toast('Keine Änderungen vorhanden.');closeModal();return}
  ev=eventOf('material_revision',data.id,data,id?headParent('material',id):[]);
  }else if(kind==='offer'){
   const url=formVal(f,'url').trim();if(!isKleinanzeigenUrl(url))throw new Error('Bitte einen HTTPS-Link von kleinanzeigen.de eintragen.');
   data={id:id||'ANG-'+uid().slice(0,8).toUpperCase(),title:formVal(f,'title').trim().slice(0,160),url,price:formNum(f,'price'),shipping:formNum(f,'shipping'),materialId:formVal(f,'materialId'),seller:formVal(f,'seller').slice(0,100),availability:formVal(f,'availability'),notes:formVal(f,'notes').slice(0,3000)};
   if(data.title.length<2)throw new Error('Angebotsbezeichnung fehlt.');if(data.price<=0)throw new Error('Bitte einen realistischen Angebotspreis größer als 0 eintragen.');
   if(id&&JSON.stringify(data)===JSON.stringify(findE('offer',id)?.data)){toast('Keine Änderungen vorhanden.');closeModal();return}
   ev=eventOf('offer_revision',data.id,data,id?headParent('offer',id):[]);
 }else if(kind==='session'){
  data={id:id||'TER-'+uid().slice(0,8).toUpperCase(),title:formVal(f,'title').trim(),date:formVal(f,'date'),start:formVal(f,'start'),end:formVal(f,'end'),kind:'werkstatt',week:formNum(f,'week'),notes:formVal(f,'notes').slice(0,3000)};
  if(data.start&&data.end&&data.start>=data.end)throw new Error('Terminende muss nach Beginn liegen.');
  if(id&&JSON.stringify(data)===JSON.stringify(findE('session',id).data)){toast('Keine Änderungen vorhanden.');closeModal();return}
  ev=eventOf('session_revision',data.id,data,id?headParent('session',id):[]);
 }else if(kind==='worklog'){
  const tid=formVal(f,'taskId'),t=findE('task',tid);if(vote('task',t).state!=='approved')throw new Error('Aufgabe ist nicht freigegeben.');
  const participants=[...f.querySelectorAll('[name=participant]:checked')].map(x=>x.value);if(!participants.length)throw new Error('Mindestens eine beteiligte Person angeben.');
  const cost=formNum(f,'cost');if(cost>0&&costsFor(events,tid)+cost>Number(t.data.budget||0)+0.0001)throw new Error('Kosten überschreiten das freigegebene Aufgabenbudget. Bitte vorab eine neue Budgetfassung genehmigen lassen.');
  data={taskId:tid,date:formVal(f,'date'),participants,hours:formNum(f,'hours'),cost,payer:formVal(f,'payer'),note:formVal(f,'note').slice(0,3000)};
  if(!data.hours||data.hours>24)throw new Error('Bitte 0,25 bis 24 Stunden eintragen.');
  ev=eventOf('worklog','LOG-'+uid(),data);
 }else if(kind==='expense'){
  const mid=formVal(f,'materialId'),m=findE('material',mid);if(vote('material',m).state!=='approved')throw new Error('Material ist nicht freigegeben.');
  const amount=formNum(f,'amount');if(!amount)throw new Error('Betrag fehlt.');
  const already=events.filter(e=>e.kind==='expense'&&e.data.materialId===mid).reduce((s,e)=>s+e.data.amount,0);
  if(already+amount>m.data.estimate+.0001)throw new Error('Einkauf würde das freigegebene Materialbudget überschreiten. Bitte zuerst Budgetänderung einstimmig freigeben.');
  const linked=m.data.taskId||'';if(linked){const t=findE('task',linked);if(!t||vote('task',t).state!=='approved')throw new Error('Verknüpfte Aufgabe muss ebenfalls freigegeben sein.');if(costsFor(events,linked)+amount>Number(t.data.budget||0)+.0001)throw new Error('Ausgabe würde das freigegebene Aufgabenbudget überschreiten. Bitte erst Kostenrahmen neu abstimmen.');}
  const offerId=formVal(f,'offerId');if(offerId){const o=findE('offer',offerId);if(!o||o.data?.materialId!==mid||vote('offer',o).state!=='approved'||o.data.availability==='Nicht verfügbar')throw new Error('Ausgewähltes Kleinanzeigenangebot muss aktuell mit 3/3 Stimmen freigegeben sein.');if(amount>offerTotal(o.data)+.0001)throw new Error('Betrag überschreitet das freigegebene Kleinanzeigenangebot.')}
   data={materialId:mid,offerId,taskId:linked,date:formVal(f,'date'),title:formVal(f,'title').slice(0,160),amount,payer:formVal(f,'payer'),note:formVal(f,'note').slice(0,3000)};
  ev=eventOf('expense','EXP-'+uid(),data);
 }else return;
 await append(ev);closeModal();toast('Gespeichert. Bitte Änderungen als JSON teilen.');}
async function handleClick(e){
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.close){closeModal();return}
 if(b.dataset.setActor){actor=b.dataset.setActor;await meta('actor',actor);closeModal();render();toast('Mitglied ausgewählt: '+who(actor));return}
 if(b.dataset.page){go(b.dataset.page);return}
 if(b.dataset.roadmapJump){const phase=document.getElementById('phase-'+b.dataset.roadmapJump);if(phase){const panel=phase.querySelector('details');if(panel)panel.open=true;phase.scrollIntoView({behavior:'smooth',block:'start'});}return}
 if(b.dataset.roadmapFilter){filterSection=b.dataset.roadmapFilter;filterSearch='';go('tasks');return}
 if(b.dataset.task){detailTask(b.dataset.task);return}
 if(b.dataset.material){detailMaterial(b.dataset.material);return}
 if(b.dataset.offer){detailOffer(b.dataset.offer);return}
 if(b.dataset.addOffer){editOffer(null,b.dataset.addOffer==='1'?'':b.dataset.addOffer);return}
 if(b.dataset.editOffer){editOffer(b.dataset.editOffer);return}
 if(b.dataset.request){showSendApproval(...b.dataset.request.split('|'));return}
 if(b.dataset.sendRequest){await sendApproval(...b.dataset.sendRequest.split('|'));return}
 if(b.dataset.copyRequest){await copyRequest(...b.dataset.copyRequest.split('|'));return}
 if(b.dataset.approvalActor){actor=b.dataset.approvalActor;await meta('actor',actor);showApprovalRequest();return}
 if(b.dataset.openSync){closeModal();go('sync');return}
 if(b.dataset.shareLog){await shareLog(b.dataset.shareLog);return}
 if(b.dataset.session){detailSession(b.dataset.session);return}
 if(b.dataset.addTask){editTask();return}
 if(b.dataset.editTask){editTask(b.dataset.editTask);return}
 if(b.dataset.addMaterial){editMaterial();return}
 if(b.dataset.editMaterial){editMaterial(b.dataset.editMaterial);return}
 if(b.dataset.addSession){editSession();return}
 if(b.dataset.editSession){editSession(b.dataset.editSession);return}
 if(b.dataset.addLog){newWorklog();return}
 if(b.dataset.logTask){newWorklog(b.dataset.logTask);return}
 if(b.dataset.addExpense){newExpense();return}
 if(b.dataset.buyMaterial){newExpense(b.dataset.buyMaterial);return}
 if(b.dataset.cast){const [type,id,choice]=b.dataset.cast.split('|'),t=findE(type,id);if(!t||t.conflict)throw new Error('Konflikt: Stimme nicht gespeichert.');let comment='';if(choice!=='yes'){const result=prompt(choice==='no'?'Grund der Ablehnung:':'Konkreten Änderungsvorschlag eingeben:');if(result===null)return;comment=result.trim().slice(0,2999);if(!comment)throw new Error('Bitte die Ablehnung oder Änderung begründen.')}await append(eventOf('vote',id,{targetType:type,revisionId:t.revision.id,choice,comment}));if(type==='task')detailTask(id);else if(type==='material')detailMaterial(id);else detailOffer(id);toast('Stimme dokumentiert. Exportiere das Protokoll für die anderen.');return}
 if(b.dataset.status){const id=b.dataset.status,t=findE('task',id),val=$('#taskState').value;if(['In Arbeit'].includes(val)&&vote('task',t).state!=='approved')throw new Error('Ohne 3/3-Freigabe darf nicht begonnen werden.');const current=entityHeads(events,'status',id);if(current.conflict)throw new Error('Statuskonflikt zuerst im Abgleich lösen.');await append(eventOf('status_revision',id,{status:val},current.heads.length?current.heads.map(x=>x.id):[baseId('status',id)]));detailTask(id);toast('Status protokolliert.');return}
 if(b.dataset.matStatus){const id=b.dataset.matStatus,m=findE('material',id),val=$('#materialState').value;if(['Bestellt','Beschafft'].includes(val)&&vote('material',m).state!=='approved')throw new Error('Erst nach 3/3-Freigabe darf bestellt oder beschafft werden.');const current=entityHeads(events,'material_status',id);if(current.conflict)throw new Error('Materialstatus-Konflikt zuerst auflösen.');await append(eventOf('material_status_revision',id,{status:val},current.heads.length?current.heads.map(x=>x.id):[baseId('material_status',id)]));detailMaterial(id);toast('Materialstatus gespeichert.');return}
 if(b.dataset.rsvp){const [id,choice]=b.dataset.rsvp.split('|');await append(eventOf('rsvp',id,{choice}));detailSession(id);toast('Verfügbarkeit gespeichert.');return}
 if(b.dataset.voidLog){if(!confirm('Dieses Arbeitsprotokoll stornieren? Der ursprüngliche Eintrag bleibt im Änderungsprotokoll dokumentiert.'))return;await append(eventOf('voidlog','VOID-'+uid(),{logId:b.dataset.voidLog}));toast('Protokoll storniert.');return}
 if(b.dataset.rename){const m=b.dataset.rename,name=$('#name-'+m).value.trim();if(name.length<2)throw new Error('Name zu kurz.');await append(eventOf('member_name',m,{name:name.slice(0,50)}));toast('Name gespeichert und für den Export erfasst.');return}
 if(b.dataset.resolve){const [type,id]=b.dataset.resolve.split('|');showResolve(type,id);return}
 if(b.dataset.resolveChoice){const [type,id,chosenId]=b.dataset.resolveChoice.split('|'),h=entityHeads(events,type,id);if(!h.conflict||h.missing.length)throw new Error('Konflikt kann nicht aufgelöst werden.');const chosen=h.heads.find(x=>x.id===chosenId);if(!chosen)throw new Error('Version nicht mehr verfügbar.');await append(eventOf(`${type}_revision`,id,chosen.data,h.heads.map(x=>x.id)));closeModal();toast('Konflikt aufgelöst. Gegebenenfalls ist neue Zustimmung erforderlich.');return}
 if(b.dataset.export){exportFile(b.dataset.export);return}
 if(b.id==='mergeFile'){await importFile(false);return}
 if(b.id==='restoreFile'){await importFile(true);return}
}
async function handleChange(e){if(e.target.id==='actorSelect'){actor=e.target.value;await meta('actor',actor);render();toast('Aktives Mitglied: '+who(actor));return}
 if(e.target.id==='sectionFilter'){filterSection=e.target.value;render();$('#sectionFilter')?.focus();return}
 if(e.target.id==='approvalFilter'){filterApproval=e.target.value;render();return}
 if(e.target.name==='materialId'&&e.target.closest('form[data-form="expense"]')){const dropdown=e.target.form.elements.namedItem('offerId');if(dropdown){const a=sortedOffers(events,e.target.value).filter(o=>o.data.availability!=='Nicht verfügbar'&&vote('offer',o).state==='approved');dropdown.innerHTML='<option value="">Kein konkretes Angebot zuordnen</option>'+a.map(o=>`<option value="${esc(o.id)}">${esc(o.data.title)} · ${money(offerTotal(o.data))}</option>`).join('');}return}
 if(e.target.id==='importFile'){const have=!!e.target.files?.[0];$('#mergeFile').disabled=!have;$('#restoreFile').disabled=!have;return}
 if(e.target.dataset.step){const [id,iStr]=e.target.dataset.step.split('|'),i=Number(iStr),t=findE('task',id);if(vote('task',t).state!=='approved')throw new Error('Erst 3/3 Freigabe einholen.');const x=stepState(events,id,i);if(x.conflict)throw new Error('Konflikt im Schritt, bitte auflösen.');const idStep=id+'#'+i;await append(eventOf('step_revision',idStep,{done:e.target.checked},x.heads.length?x.heads.map(x=>x.id):[baseId('step',idStep)]));detailTask(id);toast('Einzelschritt dokumentiert.');return}
}
function exportFile(type){const payload=transfer(events,type,deviceId),stamp=new Date().toISOString().slice(0,16).replaceAll(':','-');downloadFile(`Werkstatt-${type==='backup'?'Vollsicherung':'Aenderungen'}-${stamp}.json`,JSON.stringify(payload,null,2));toast(type==='backup'?'Vollsicherung erstellt.':'Änderungsprotokoll erstellt. Bitte mit der Gruppe teilen.');}
function downloadFile(filename,txt){const blob=new Blob([txt],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function importFile(replace){const file=$('#importFile')?.files?.[0];if(!file)throw new Error('Bitte zuerst eine JSON-Datei auswählen.');const obj=parseTransfer(await file.text());if(replace&&obj.exportType!=='backup')throw new Error('Für eine Wiederherstellung wird eine vollständige Projektsicherung benötigt.');
 if(replace){if(!confirm('ACHTUNG: Alle aktuellen Daten auf DIESEM GERÄT durch diese Sicherung ersetzen? Zuerst wird automatisch eine Sicherungsdatei heruntergeladen.'))return;exportFile('backup');await txPut('events',obj.events,true);events=sortEvents(obj.events);}
 else {const combined=reconcile(events,obj.events);if(combined.added===0){toast(`Keine neuen Änderungen. ${combined.duplicates} bereits bekannt.`);return}await txPut('events',combined.events);events=combined.events;const conflicts=conflictingEntities(events).length;toast(`${combined.added} Änderungen übernommen, ${combined.duplicates} Duplikate ignoriert, ${conflicts} Konflikte.`)}
 localStorage.setItem('werkstatt-last-import',new Date().toLocaleString('de-DE'));render();}
function catchUI(fn){return async e=>{try{await fn(e)}catch(err){console.error(err);toast(err.message||'Fehler aufgetreten.',true);render()}}}
async function init(){db=await opendb();let id=await meta('device');deviceId=id||uid();if(!id)await meta('device',deviceId);const savedActor=await meta('actor');actor=savedActor||'a';if(!MEMBER_IDS.includes(actor))actor='a';events=sortEvents(await txAll('events'));const hash=location.hash.replace('#','');page=nav.some(x=>x[0]===hash)?hash:'dashboard';render();if(hash.startsWith('approval='))showApprovalRequest();else if(!savedActor)openModal('Willkommen · Mitglied auswählen',`<div class="notice">Diese Werkstatt wird von drei gleichberechtigten Personen organisiert. Wähle, wer dieses Gerät nutzt. Die Auswahl kann später jederzeit oben geändert werden.</div><div class="sectionlist spacing">${MEMBER_IDS.map(m=>`<button class="btn primary" data-set-actor="${m}" style="justify-content:flex-start">${esc(who(m))}</button>`).join('')}</div><div class="muted smalltxt spacing">Die Auswahl ist keine technische Identitätsprüfung. Bei gemeinsam genutzten Geräten vor jeder Zustimmung das aktive Mitglied prüfen.</div>`);document.addEventListener('click',catchUI(handleClick));$('#modal').addEventListener('click',e=>{if(e.target.matches('.modal-backdrop'))closeModal()});document.addEventListener('change',catchUI(handleChange));document.addEventListener('submit',catchUI(async e=>{if(e.target.id==='editForm'){e.preventDefault();await saveForm(e.target)}}));document.addEventListener('input',e=>{if(e.target.id==='searchTasks'){filterSearch=e.target.value;const caret=e.target.selectionStart;render();const next=$('#searchTasks');next?.focus();next?.setSelectionRange(caret,caret)}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('#shareBtn').addEventListener('click',catchUI(async()=>{if(navigator.share)await navigator.share({title:'MAAK. – Gemeinsam machen',url:location.href.split('#')[0]});else{await navigator.clipboard.writeText(location.href.split('#')[0]);toast('Link in die Zwischenablage kopiert.')}}));window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(h.startsWith('approval=')){showApprovalRequest();return}if(nav.some(x=>x[0]===h)){page=h;render()}});
 try{const channel=new BroadcastChannel('werkstatt-sync');channel.onmessage=()=>reload()}catch{}
 if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
 if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});
}
init().catch(err=>{$('#content').innerHTML=`<div class="notice error">Datenbank konnte nicht geöffnet werden: ${esc(err.message)}. Bitte den Browser im normalen Modus verwenden.</div>`});
